"""Typed predicate AST and evaluator.

Expressions are compiled once and evaluate against a lexical scope stack.  A
scope maps a name to ``(value, type_node)``.  Keeping the type alongside the
value lets the same compiled predicate be used with transition guards, module
preconditions and re-bound filter applications, while still implementing
modular integer arithmetic exactly.
"""

from .model import (AliasType, ArrayType, BoolType, BOOL, CharType, EnumType,
                    IntType, StringType, StructType, VoidType, underlying)
from .pattern import compile_pattern

MISSING = object()
BINARY_OPS = {
    "eq", "ne", "lt", "le", "gt", "ge", "add", "sub",
    "and", "or", "implies",
}


def deep_equal(left, right, type_node):
    """Typed, recursive equality (notably keeping bool and int distinct)."""
    type_node = underlying(type_node)
    if isinstance(type_node, BoolType):
        return (isinstance(left, bool) and isinstance(right, bool)
                and left == right)
    if isinstance(type_node, IntType):
        return (isinstance(left, int) and not isinstance(left, bool)
                and isinstance(right, int) and not isinstance(right, bool)
                and left == right)
    if isinstance(type_node, (CharType, StringType, EnumType)):
        return (isinstance(left, str) and isinstance(right, str)
                and left == right)
    if isinstance(type_node, ArrayType):
        if not isinstance(left, list) or not isinstance(right, list):
            return False
        if len(left) != len(right) or len(left) != type_node.size:
            return False
        return all(deep_equal(a, b, type_node.element)
                   for a, b in zip(left, right))
    if isinstance(type_node, StructType):
        if not isinstance(left, dict) or not isinstance(right, dict):
            return False
        if len(left) != len(type_node.fields) or len(right) != len(type_node.fields):
            return False
        for field_name, field_type in type_node.fields:
            if field_name not in left or field_name not in right:
                return False
            if not deep_equal(left[field_name], right[field_name], field_type):
                return False
        return True
    if isinstance(type_node, VoidType):
        return left is None and right is None
    return left == right


class ExprNode:
    __slots__ = ()

    def eval(self, scopes):
        raise NotImplementedError


class VarExpr(ExprNode):
    __slots__ = ("name",)

    def __init__(self, name):
        self.name = name

    def eval(self, scopes):
        for scope in reversed(scopes):
            value = scope.get(self.name, MISSING)
            if value is not MISSING:
                return value
        raise KeyError(self.name)


class ConstExpr(ExprNode):
    __slots__ = ("value", "type")

    def __init__(self, value, type_node):
        self.value = value
        self.type = type_node

    def eval(self, scopes):
        return self.value, self.type


class FieldExpr(ExprNode):
    __slots__ = ("expr", "field")

    def __init__(self, expr, field):
        self.expr = expr
        self.field = field

    def eval(self, scopes):
        value, type_node = self.expr.eval(scopes)
        struct_type = underlying(type_node)
        field_type = struct_type.field_map[self.field]
        return value[self.field], field_type


class IndexExpr(ExprNode):
    __slots__ = ("expr", "index")

    def __init__(self, expr, index):
        self.expr = expr
        self.index = index

    def eval(self, scopes):
        value, type_node = self.expr.eval(scopes)
        array_type = underlying(type_node)
        return value[self.index], array_type.element


class AllExpr(ExprNode):
    __slots__ = ("binding", "array_expr", "body")

    def __init__(self, binding, array_expr, body):
        self.binding = binding
        self.array_expr = array_expr
        self.body = body

    def eval(self, scopes):
        array_value, array_type = self.array_expr.eval(scopes)
        element_type = underlying(array_type).element
        scope = {}
        scopes.append(scope)
        try:
            for element in array_value:
                scope[self.binding] = (element, element_type)
                if not self.body.eval(scopes)[0]:
                    return False, BOOL
            return True, BOOL
        finally:
            scopes.pop()


class MatchExpr(ExprNode):
    __slots__ = ("string_expr", "pattern")

    def __init__(self, string_expr, pattern):
        self.string_expr = string_expr
        self.pattern = pattern

    def eval(self, scopes):
        value, _ = self.string_expr.eval(scopes)
        return self.pattern.fullmatch(value), BOOL


class NotExpr(ExprNode):
    __slots__ = ("expr",)

    def __init__(self, expr):
        self.expr = expr

    def eval(self, scopes):
        return (not self.expr.eval(scopes)[0]), BOOL


class BinExpr(ExprNode):
    __slots__ = ("op", "left", "right")

    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right

    def eval(self, scopes):
        op = self.op
        if op == "and":
            left_value = self.left.eval(scopes)[0]
            if not left_value:
                return False, BOOL
            return bool(self.right.eval(scopes)[0]), BOOL
        if op == "or":
            left_value = self.left.eval(scopes)[0]
            if left_value:
                return True, BOOL
            return bool(self.right.eval(scopes)[0]), BOOL
        if op == "implies":
            left_value = self.left.eval(scopes)[0]
            if not left_value:
                return True, BOOL
            return bool(self.right.eval(scopes)[0]), BOOL

        left_value, left_type = self.left.eval(scopes)
        right_value, _ = self.right.eval(scopes)
        if op == "eq":
            return deep_equal(left_value, right_value, left_type), BOOL
        if op == "ne":
            return not deep_equal(left_value, right_value, left_type), BOOL
        if op == "lt":
            return left_value < right_value, BOOL
        if op == "le":
            return left_value <= right_value, BOOL
        if op == "gt":
            return left_value > right_value, BOOL
        if op == "ge":
            return left_value >= right_value, BOOL
        if op in ("add", "sub"):
            bits = underlying(left_type).bits
            modulus = 1 << bits
            if op == "add":
                result = (left_value + right_value) % modulus
            else:
                result = (left_value - right_value) % modulus
            return result, left_type
        raise ValueError("unknown binary operation")


class ExprCompiler:
    __slots__ = ("types",)

    def __init__(self, types):
        self.types = types

    def compile(self, raw):
        if not isinstance(raw, list) or not raw:
            raise ValueError("invalid predicate")
        tag = raw[0]
        if tag == "var":
            return VarExpr(raw[1])
        if tag == "const":
            return ConstExpr(raw[2], self.types.get(raw[1]))
        if tag == "field":
            return FieldExpr(self.compile(raw[1]), raw[2])
        if tag == "index":
            return IndexExpr(self.compile(raw[1]), raw[2])
        if tag == "all":
            return AllExpr(raw[1], self.compile(raw[2]), self.compile(raw[3]))
        if tag == "match":
            return MatchExpr(self.compile(raw[1]), compile_pattern(raw[2]))
        if tag == "not":
            return NotExpr(self.compile(raw[1]))
        if tag in BINARY_OPS:
            return BinExpr(tag, self.compile(raw[1]), self.compile(raw[2]))
        raise ValueError("unknown predicate form")


def structural_key(value):
    """Canonical, object-order-independent key for a JSON-like expression."""
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("int", value)
    if isinstance(value, float):
        return ("float", value)
    if isinstance(value, str):
        return ("str", value)
    if isinstance(value, list):
        return ("list", tuple(structural_key(item) for item in value))
    if isinstance(value, dict):
        return ("dict", tuple(sorted((key, structural_key(item))
                                     for key, item in value.items())))
    return ("other", repr(value))
